package net.civeira.phylax.features.notification.outbox.infrastructure.scheduler;

import static org.mockito.Mockito.doThrow;
import static org.mockito.Mockito.verify;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;

import net.civeira.phylax.features.notification.outbox.application.service.NotificationDispatchService;

/**
 * Unit tests for {@link NotificationDispatchScheduler}.
 */
class NotificationDispatchSchedulerTest {

  @Mock
  private NotificationDispatchService dispatchService;

  @InjectMocks
  private NotificationDispatchScheduler scheduler;

  @BeforeEach
  void setUp() {
    MockitoAnnotations.openMocks(this);
  }

  @Test
  @DisplayName("dispatch() delegates to NotificationDispatchService")
  void dispatch_delegatesToService() {
    scheduler.dispatch();

    verify(dispatchService).dispatch();
  }

  @Test
  @DisplayName("dispatch() swallows exceptions thrown by the service")
  void dispatch_swallowsExceptionFromService() {
    doThrow(new RuntimeException("SMTP failure")).when(dispatchService).dispatch();

    // Must not propagate the exception
    scheduler.dispatch();

    verify(dispatchService).dispatch();
  }
}
